B.af5=new A.dK("1. \ubaa9\uc801\uacfc \uc801\uc6a9","\uc774 \uc57d\uad00\uc740 \uacb0(GYEOL)\uc774 \uc81c\uacf5\ud558\ub294 \uc18c\uac1c\ud305, \uad00\uacc4\ud615 \ucee4\ubba4\ub2c8\ud2f0, \ub9e4\uce6d\ub9e4\ub2c8\uc800, \ucc44\ud305, \ud3ec\uc778\ud2b8 \ubc0f \uace0\uac1d\uc9c0\uc6d0 \uc11c\ube44\uc2a4\uc758 \uc774\uc6a9 \uc870\uac74\uacfc \ud68c\uc6d0\uc758 \uad8c\ub9ac\xb7\uc758\ubb34\ub97c \uc815\ud569\ub2c8\ub2e4.")
B.af3=new A.dK("2. \uac00\uc785 \uc790\uaca9\uacfc \ubcf8\uc778 \uc815\ubcf4","\ud68c\uc6d0\uc740 \ub9cc 18\uc138 \uc774\uc0c1\uc774\uc5b4\uc57c \ud558\uba70 \ubcf8\uc778\uc758 \uc804\ud654\ubc88\ud638 \ub610\ub294 \uc774\uba54\uc77c \uacc4\uc815, \uc2e4\uc81c \uc0dd\ub144, \uc131\ubcc4, \uc9c0\uc5ed \ubc0f \ubcf8\uc778 \uc0ac\uc9c4\uc744 \uc0ac\uc6a9\ud574\uc57c \ud569\ub2c8\ub2e4. \ud0c0\uc778\uc758 \uc2e0\uc6d0\uc774\ub098 \uc0ac\uc9c4\uc744 \uc0ac\uc6a9\ud558\uac70\ub098 \uac00\uc785 \uc81c\ud55c\uc744 \uc6b0\ud68c\ud558\uba74 \uacc4\uc815\uc774 \uc989\uc2dc \uc81c\ud55c\ub420 \uc218 \uc788\uc2b5\ub2c8\ub2e4.")
B.af7=new A.dK("3. \ud504\ub85c\ud544 \uc0ac\uc9c4 \uc801\ud569\uc131 \uac80\uc0ac","\uc0ac\uc9c4\uc740 \uc5bc\uad74 \uc874\uc7ac \uc5ec\ubd80, \ud55c \uc0ac\ub78c \uc5ec\ubd80, \uc815\uba74\uc131, \ud06c\uae30, \ud750\ub9bc, \ub178\ucd9c, \uac00\ub9bc, \ub9c8\uc2a4\ud06c\xb7\uc120\uae00\ub77c\uc2a4 \ub4f1 \ud504\ub85c\ud544 \uc2dd\ubcc4 \ubc29\ud574 \uc694\uc18c\ub97c \ud655\uc778\ud569\ub2c8\ub2e4. \uc774\ub294 \uc2e0\uc6d0 \uc2dd\ubcc4\uc774\ub098 \uc0dd\uccb4\uc778\uc99d\uc774 \uc544\ub2c8\uba70 \uc790\ub3d9 \ud310\uc815\uc774 \ubd88\ud655\uc2e4\ud55c \uacbd\uc6b0 \uc6b4\uc601\uc790 \uac80\uc218\ub85c \uc804\ud658\ub429\ub2c8\ub2e4.")
B.afn=new A.dK("4. \ucd94\ucc9c\xb7\uc778\uc5f0 \uc2e0\uccad\xb7\ub9e4\uce6d","\ucd94\ucc9c\uc740 \ud68c\uc6d0\uc774 \uc785\ub825\ud55c \uc131\ubcc4, \ub098\uc774, \uac70\ub9ac, \uad00\uacc4 \ubaa9\uc801, \ucc28\ub2e8\xb7\uc5f0\uacb0 \uc0c1\ud0dc \ub4f1\uc744 \uae30\uc900\uc73c\ub85c \uc81c\uacf5\ub429\ub2c8\ub2e4. \uc0c1\ub300\ubc29\uc758 \uc218\ub77d \uc804\uc5d0\ub294 \uc5f0\uacb0\uc774 \uc131\ub9bd\ud558\uc9c0 \uc54a\uc73c\uba70 \ub204\uad6c\ub3c4 \ub2f5\ubcc0\uc774\ub098 \ub9cc\ub0a8\uc744 \uac15\uc694\ud560 \uc218 \uc5c6\uc2b5\ub2c8\ub2e4.")
B.afi=new A.dK("5. \uacb0 \ub9e4\ub2c8\uc800","\ub9e4\uce6d\ub9e4\ub2c8\uc800\ub294 \ud68c\uc6d0\uc774 \uc790\ubc1c\uc801\uc73c\ub85c \uc2e0\uccad\ud55c \uacbd\uc6b0\uc5d0\ub9cc \uc18c\uac1c \ud6c4\ubcf4\uc640 \uc18c\uac1c \uc774\uc720\ub97c \uc81c\uc548\ud569\ub2c8\ub2e4. \ud68c\uc6d0\uc740 \uc81c\uc548\uc744 \uac70\uc808\ud560 \uc218 \uc788\uace0, \uc218\ub77d\ud558\ub354\ub77c\ub3c4 \uc0c1\ub300 \ud68c\uc6d0\uc758 \ub3d9\uc758\uac00 \uc788\uc5b4\uc57c \uc5f0\uacb0\ub429\ub2c8\ub2e4. \uc6b4\uc601 \uacc4\uc815\uc740 \uc0ac\uc6a9\uc790 \ud654\uba74\uc5d0 \ubcc4\ub3c4\ub85c \ud45c\uc2dc\ub429\ub2c8\ub2e4.")
B.af4=new A.dK("6. \ub77c\uc6b4\uc9c0\uc640 \ucc44\ud305","\ud68c\uc6d0\uc740 \ubc95\ub839\uacfc \ucee4\ubba4\ub2c8\ud2f0 \uac00\uc774\ub4dc\ub97c \uc900\uc218\ud574\uc57c \ud569\ub2c8\ub2e4. \uc131\uc801 \uac70\ub798 \uc720\ub3c4, \uae08\uc804\xb7\ud22c\uc790 \uc694\uad6c, \uc704\ud611, \ud610\uc624, \ubd88\ubc95 \uac70\ub798, \uc5f0\ub77d\ucc98 \uc218\uc9d1, \uc2a4\ud338, \ud0c0\uc778\uc758 \uac1c\uc778\uc815\ubcf4 \uacf5\uac1c\ub294 \uae08\uc9c0\ub429\ub2c8\ub2e4. \uc2e0\uace0\xb7\ucc28\ub2e8 \uae30\ub2a5\uc744 \uc545\uc6a9\ud574\uc11c\ub3c4 \uc548 \ub429\ub2c8\ub2e4.")
B.af9=new A.dK("7. \ud3ec\uc778\ud2b8\uc640 \uc778\uc571\uacb0\uc81c","\ub514\uc9c0\ud138 \ud3ec\uc778\ud2b8\ub294 \uc571 \uc548\uc758 \uae30\ub2a5\uc5d0\ub9cc \uc0ac\uc6a9\ud560 \uc218 \uc788\uace0 \ud604\uae08\uc73c\ub85c \ud658\uc804\ub418\uc9c0 \uc54a\uc2b5\ub2c8\ub2e4. Apple App Store \ub610\ub294 Google Play\uc5d0\uc11c \uc644\ub8cc\ub41c \uacb0\uc81c\ub294 \uc11c\ubc84 \uc601\uc218\uc99d \uac80\uc99d \ud6c4 \uc9c0\uae09\ub429\ub2c8\ub2e4. \uc911\ubcf5\xb7\ucde8\uc18c\xb7\ud658\ubd88\xb7\ub3c4\uc6a9 \uac70\ub798\ub294 \uc9c0\uae09 \ucde8\uc18c \ub610\ub294 \ud68c\uc218\ub420 \uc218 \uc788\uc2b5\ub2c8\ub2e4.")
B.af0=new A.dK("8. \uc81c\uc7ac\uc640 \uc774\uc758\uc81c\uae30","\uc6b4\uc601\uc790\ub294 \uc548\uc804\uc744 \uc704\ud574 \ucf58\ud150\uce20 \uc228\uae40, \uc0ac\uc9c4 \uc7ac\uac80\uc218, \uae30\ub2a5 \uc81c\ud55c, \uacc4\uc815 \uc815\uc9c0 \ub610\ub294 \uc0ad\uc81c\ub97c \ud560 \uc218 \uc788\uc2b5\ub2c8\ub2e4. \ud68c\uc6d0\uc740 \uc571 \ub0b4 \uace0\uac1d\uc9c0\uc6d0\uc5d0\uc11c \uadfc\uac70\uc640 \ud568\uaed8 \uc774\uc758\uc81c\uae30\ub97c \uc81c\ucd9c\ud560 \uc218 \uc788\uc2b5\ub2c8\ub2e4.")
B.af6=new A.dK("9. \uacc4\uc815 \uc0ad\uc81c","\ud68c\uc6d0\uc740 \uc124\uc815\uc5d0\uc11c \uacc4\uc815 \uc0ad\uc81c\ub97c \uc694\uccad\ud560 \uc218 \uc788\uc2b5\ub2c8\ub2e4. \ubc95\ub839\uc0c1 \ubcf4\uc874 \uc758\ubb34\uac00 \uc788\ub294 \uacb0\uc81c\xb7\ubd84\uc7c1\xb7\uac10\uc0ac \uae30\ub85d\uc744 \uc81c\uc678\ud55c \ud504\ub85c\ud544\uacfc \uc11c\ube44\uc2a4 \ub370\uc774\ud130\ub294 \uc6b4\uc601 \uc815\ucc45\uc5d0 \ub530\ub77c \uc0ad\uc81c \ub610\ub294 \ube44\uc2dd\ubcc4\ud654\ub429\ub2c8\ub2e4.")
B.afl=new A.dK("10. \ubb38\uc758","\uc57d\uad00, \uc2e0\uace0 \ub300\uc751, \uac1c\uc778\uc815\ubcf4 \ub610\ub294 \uc544\ub3d9 \uc548\uc804 \uad00\ub828 \ubb38\uc758\ub294 \uc571 \ub0b4 \uace0\uac1d\uc9c0\uc6d0\uc73c\ub85c \uc811\uc218\ud569\ub2c8\ub2e4. \uae34\uae09\ud55c \uc704\ud5d8\uc774 \uc788\ub294 \uacbd\uc6b0 \uc571 \uc2e0\uace0\uc640 \ud568\uaed8 \ud604\uc9c0 \uc218\uc0ac\xb7\uae34\uae09 \uae30\uad00\uc5d0 \uc5f0\ub77d\ud574\uc57c \ud569\ub2c8\ub2e4.")
B.UY=s([B.af5,B.af3,B.af7,B.afn,B.afi,B.af4,B.af9,B.af0,B.af6,B.afl],t.IY)
