B.afb=new A.dK("1. \ucc98\ub9ac\ud558\ub294 \uc815\ubcf4","\uac00\uc785 \uc2dd\ubcc4\uc815\ubcf4(\uc804\ud654\ubc88\ud638 \ud574\uc2dc, \uc774\uba54\uc77c, Firebase \uc2dd\ubcc4\uc790), \ud504\ub85c\ud544(\ub2c9\ub124\uc784, \uc0dd\ub144, \uc131\ubcc4, \uc9c0\uc5ed, \uc9c1\uc5c5, \uc18c\uac1c, \uad00\uc2ec\uc0ac, \uc120\ud638\uc870\uac74), \uc704\uce58\uc5d0\uc11c \ubcc0\ud658\ud55c \uc9c0\uc5ed\uacfc \uac70\ub9ac \uacc4\uc0b0\uc6a9 \uc88c\ud45c, \ud504\ub85c\ud544 \uc0ac\uc9c4\uacfc \uac80\uc218 \uacb0\uacfc, \uc778\uc5f0 \uc2e0\uccad\xb7\ub9e4\uce6d\xb7\ucc44\ud305\xb7\ub77c\uc6b4\uc9c0\xb7\uc2e0\uace0\xb7\ucc28\ub2e8 \uae30\ub85d, \ud3ec\uc778\ud2b8\xb7\ucd94\ucc9c\uc778\xb7\uacb0\uc81c \uac70\ub798 \uc2dd\ubcc4\uc790, \uae30\uae30 \ud478\uc2dc \ud1a0\ud070\uacfc \uc624\ub958 \uae30\ub85d\uc744 \ucc98\ub9ac\ud569\ub2c8\ub2e4.")
B.afg=new A.dK("2. \ucc98\ub9ac \ubaa9\uc801","\ud68c\uc6d0 \uc778\uc99d\uacfc \uc5f0\ub839 \ud655\uc778, \ud504\ub85c\ud544 \uc81c\uacf5, \uc870\uac74 \uae30\ubc18 \ucd94\ucc9c, \uc0ac\uc9c4 \uc548\uc804\uac80\uc218, \ub9e4\uce6d\xb7\ucc44\ud305, \ucee4\ubba4\ub2c8\ud2f0 \uc6b4\uc601, \uc2e0\uace0 \ub300\uc751, \ud3ec\uc778\ud2b8\xb7\uacb0\uc81c \uac80\uc99d, \ubd80\uc815 \uc774\uc6a9 \ubc29\uc9c0, \uc624\ub958 \ubd84\uc11d\uacfc \uace0\uac1d\uc9c0\uc6d0\uc744 \uc704\ud574 \uc0ac\uc6a9\ud569\ub2c8\ub2e4.")
B.afd=new A.dK("3. \uc0ac\uc9c4\uacfc \uc5bc\uad74 \ub370\uc774\ud130","\uacb0\uc740 \ud2b9\uc815 \uc778\ubb3c\uc744 \uc54c\uc544\ub0b4\ub294 \uc5bc\uad74 \uc778\uc2dd, \uc5bc\uad74 \uc784\ubca0\ub529 \uc800\uc7a5, \uc2e0\ubd84\uc99d \ub300\uc870, \uac10\uc815\xb7\uc778\uc885 \ucd94\uc815\uc744 \ud558\uc9c0 \uc54a\uc2b5\ub2c8\ub2e4. \uc0ac\uc9c4 \uc801\ud569\uc131 \ud310\uc815\uc5d0 \ud544\uc694\ud55c \uc5bc\uad74 \uc704\uce58\xb7\uac01\ub3c4\xb7\ud488\uc9c8 \uc218\uce58\ub294 \uac80\uc218\uc640 \uac10\uc0ac \ubaa9\uc801\uc73c\ub85c\ub9cc \uc81c\ud55c\uc801\uc73c\ub85c \uc800\uc7a5\ub429\ub2c8\ub2e4.")
B.af8=new A.dK("4. \uc678\ubd80 \ucc98\ub9ac\uc790","\uc778\uc99d\xb7\ud478\uc2dc\xb7\uc624\ub958 \ubd84\uc11d\uc744 \uc704\ud55c Firebase, \uc0ac\uc9c4 \ud488\uc9c8 \ud310\uc815\uc744 \uc704\ud55c Azure AI Face, \uc571 \uacb0\uc81c\ub97c \uc704\ud55c Apple\xb7Google, \uc11c\ubc84\xb7\ub370\uc774\ud130\ubca0\uc774\uc2a4 \uc6b4\uc601 \uc0ac\uc5c5\uc790\uac00 \ud544\uc694\ud55c \ubc94\uc704\uc5d0\uc11c \uc815\ubcf4\ub97c \ucc98\ub9ac\ud560 \uc218 \uc788\uc2b5\ub2c8\ub2e4. \uc678\ubd80 \ucc98\ub9ac\uc790, \ucc98\ub9ac \uc704\uce58\uc640 \ubcf4\ud638\uc870\uce58\ub294 \uc571\uacfc \uacf5\uac1c \uac1c\uc778\uc815\ubcf4\ucc98\ub9ac\ubc29\uce68\uc5d0\uc11c \ucd5c\uc2e0 \ub0b4\uc6a9\uc73c\ub85c \uc548\ub0b4\ud569\ub2c8\ub2e4.")
B.afa=new A.dK("5. \ubcf4\uc720\uc640 \ud30c\uae30","\uacc4\uc815 \ub370\uc774\ud130\ub294 \ud68c\uc6d0 \ud0c8\ud1f4 \ub610\ub294 \ucc98\ub9ac \ubaa9\uc801 \ub2ec\uc131 \uc2dc \uc0ad\uc81c\ud569\ub2c8\ub2e4. \uacb0\uc81c\xb7\ubd84\uc7c1\xb7\ubd80\uc815\uc774\uc6a9 \ubc29\uc9c0\xb7\uac10\uc0ac \uae30\ub85d\uc740 \uad00\ub828 \ubc95\ub839\uacfc \uc6b4\uc601\uc815\ucc45\uc5d0\uc11c \uc815\ud55c \uae30\uac04 \ub3d9\uc548 \ubd84\ub9ac \ubcf4\uad00\ud55c \ub4a4 \ud30c\uae30\ud569\ub2c8\ub2e4. \ubc18\ub824 \uc0ac\uc9c4\uc740 \uc774\uc758\uc81c\uae30\uc640 \uc548\uc804 \uac80\uc218\uc5d0 \ud544\uc694\ud55c \ucd5c\uc18c \uae30\uac04\ub9cc \ubcf4\uad00\ud558\uace0 \ubaa9\uc801\uc774 \ub05d\ub098\uba74 \uc548\uc804\ud558\uac8c \ud30c\uae30\ud569\ub2c8\ub2e4.")
B.afm=new A.dK("6. \ud68c\uc6d0\uc758 \uad8c\ub9ac","\ud68c\uc6d0\uc740 \uc571\uc5d0\uc11c \ud504\ub85c\ud544 \uc218\uc815, \uc704\uce58\xb7\uc54c\ub9bc \uc124\uc815 \ubcc0\uacbd, \uc0ac\uc9c4 \uc0ad\uc81c, \ucc28\ub2e8 \ud574\uc81c, \uacc4\uc815 \uc0ad\uc81c\ub97c \ud560 \uc218 \uc788\uc2b5\ub2c8\ub2e4. \uc5f4\ub78c\xb7\uc815\uc815\xb7\ucc98\ub9ac\uc815\uc9c0\xb7\uc0ad\uc81c \uc694\uccad\uc740 \uc571 \ub0b4 \uace0\uac1d\uc9c0\uc6d0\uc5d0\uc11c \uc811\uc218\ud560 \uc218 \uc788\uc2b5\ub2c8\ub2e4.")
B.afk=new A.dK("7. \ubcf4\ud638\uc870\uce58","\uc804\uc1a1\uad6c\uac04 \uc554\ud638\ud654, \ube44\ubc00\ubc88\ud638 \ub2e8\ubc29\ud5a5 \ud574\uc2dc, \uc804\ud654\ubc88\ud638 \ud574\uc2dc, \ucd5c\uc18c\uad8c\ud55c \uad00\ub9ac\uc790 \uc811\uadfc, \uac10\uc0ac\ub85c\uadf8, \ub9cc\ub8cc\ud615 \ud1a0\ud070, \ube44\uacf5\uac1c \uc800\uc7a5\uc18c, \uc2e0\uace0\xb7\ucc28\ub2e8, \uc571 \ubb34\uacb0\uc131 \uac80\uc99d\uc744 \uc0ac\uc6a9\ud569\ub2c8\ub2e4. \ube44\ubc00\ud0a4\ub294 \uc571\uacfc \uacf5\uac1c \uc800\uc7a5\uc18c\uc5d0 \ud3ec\ud568\ud558\uc9c0 \uc54a\uc2b5\ub2c8\ub2e4.")
